// ================= EDIT THIS CONFIG =================
const CONFIG = {
  LIVEKIT_URL: 'wss://aicalling-72j0sh1j.livekit.cloud',
  LIVEKIT_API_KEY: 'APIisp9fBx9gVd6',
  LIVEKIT_API_SECRET: 'DtkfIBY9IF50TX0M26vq8fF7lfoLvhltgtnjDlePmXAA',
  LIVEKIT_SIP_TRUNK_ID: 'ST_3k7G4MrWazTG', // LiveKit outbound trunk pointing at Vobiz (lk sip outbound list)
  AGENT_NAME: 'telugu-caller',             // must match AGENT_NAME in agent.py
  WEBHOOK_SECRET: 'change-this-secret',    // callers must send it as header x-webhook-secret
  DEFAULT_VOICE_ID: 'YOUR_CARTESIA_VOICE_ID',
  DEFAULT_COUNTRY_CODE: '91',
  MAX_CALL_SECONDS: 300,
  RESULT_WEBHOOK_URL: '',                  // optional: your backend URL for call.connected / call.failed events
};
// =====================================================

const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};
const reject = (status, error) => [{ json: { valid: false, http_status: status, error } }];

if ((headers['x-webhook-secret'] || '') !== CONFIG.WEBHOOK_SECRET) return reject(401, 'unauthorized');

// ---- phone number -> E.164
let raw = String(body.phone || body.to || '').replace(/[\s\-().]/g, '');
if (raw.startsWith('00')) raw = '+' + raw.slice(2);
let phone = raw;
if (!raw.startsWith('+')) {
  if (/^\d{10}$/.test(raw)) phone = '+' + CONFIG.DEFAULT_COUNTRY_CODE + raw;
  else if (/^0\d{10}$/.test(raw)) phone = '+' + CONFIG.DEFAULT_COUNTRY_CODE + raw.slice(1);
  else if (/^91\d{10}$/.test(raw)) phone = '+' + raw;
  else return reject(400, 'invalid phone number');
}
const valid = phone.startsWith('+91') ? /^\+91[6-9]\d{9}$/.test(phone) : /^\+[1-9]\d{7,14}$/.test(phone);
if (!valid) return reject(400, 'invalid phone number');

let crypto;
try {
  crypto = require('crypto');
} catch (e) {
  return reject(500, 'crypto not allowed: set NODE_FUNCTION_ALLOW_BUILTIN=crypto on your n8n instance');
}

const callId = 'c' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
const roomName = 'call-' + callId;

// metadata that the LiveKit agent receives
const meta = {
  call_id: callId,
  phone,
  name: body.name || '',
  language: body.language || 'te',
  purpose: body.purpose || '',
  system_prompt: body.system_prompt || '',
  first_message: body.first_message || '',
  voice_id: body.voice_id || CONFIG.DEFAULT_VOICE_ID,
  variables: body.variables || {},
  max_duration_sec: Number(body.max_duration_sec) || CONFIG.MAX_CALL_SECONDS,
};

// ---- LiveKit access token (HS256 JWT) with room + SIP grants
const b64u = (x) => Buffer.from(typeof x === 'string' ? x : JSON.stringify(x)).toString('base64url');
const now = Math.floor(Date.now() / 1000);
const head = b64u({ alg: 'HS256', typ: 'JWT' });
const claims = b64u({
  iss: CONFIG.LIVEKIT_API_KEY,
  sub: 'n8n-dialer',
  nbf: now - 5,
  exp: now + 600,
  video: { roomCreate: true, roomAdmin: true, room: roomName },
  sip: { admin: true, call: true },
});
const sig = crypto.createHmac('sha256', CONFIG.LIVEKIT_API_SECRET).update(head + '.' + claims).digest('base64url');

return [{
  json: {
    valid: true,
    call_id: callId,
    room_name: roomName,
    phone,
    name: meta.name,
    http_url: CONFIG.LIVEKIT_URL.replace(/^wss:/, 'https:').replace(/^ws:/, 'http:').replace(/\/+$/, ''),
    token: head + '.' + claims + '.' + sig,
    trunk_id: CONFIG.LIVEKIT_SIP_TRUNK_ID,
    agent_name: CONFIG.AGENT_NAME,
    dispatch_metadata: JSON.stringify(meta),
    notify_url: CONFIG.RESULT_WEBHOOK_URL,
    notify_secret: CONFIG.WEBHOOK_SECRET,
  },
}];

const p = $('Prepare Call').first().json;
const r = $input.first().json || {};
return [{
  json: {
    event: 'call.connected',
    call_id: p.call_id,
    phone: p.phone,
    name: p.name,
    room: p.room_name,
    sip_call_id: r.sipCallId || r.sip_call_id || null,
    at: new Date().toISOString(),
    notify_url: p.notify_url,
    notify_secret: p.notify_secret,
  },
}];

const p = $('Prepare Call').first().json;
const e = $input.first().json || {};
const reason = (e.error && (e.error.message || e.error.description)) || e.message || JSON.stringify(e).slice(0, 400);
return [{
  json: {
    event: 'call.failed',
    call_id: p.call_id,
    phone: p.phone,
    name: p.name,
    room: p.room_name,
    reason: String(reason),
    at: new Date().toISOString(),
    notify_url: p.notify_url,
    notify_secret: p.notify_secret,
  },
}];

// ================= EDIT THIS CONFIG =================
const CONFIG = {
  WEBHOOK_SECRET: 'change-this-secret',   // same as the agent's N8N_WEBHOOK_SECRET
  GROQ_API_KEY: 'YOUR_GROQ_API_KEY',
  GROQ_MODEL: 'llama-3.3-70b-versatile',
  RESULT_WEBHOOK_URL: '',                 // optional: your backend / CRM endpoint for final results
};
// =====================================================

const item = $input.first().json;
const headers = item.headers || {};
const b = item.body || {};

if ((headers['x-webhook-secret'] || '') !== CONFIG.WEBHOOK_SECRET) {
  return [{ json: { authorized: false } }];
}

const transcript = Array.isArray(b.transcript) ? b.transcript : [];
const transcriptText = transcript.map((t) => (t.role === 'assistant' ? 'AI' : 'Customer') + ': ' + t.text).join('\n');
const hasUserSpeech = transcript.some((t) => t.role === 'user');

const system =
  'You analyse phone-call transcripts (Telugu, sometimes mixed with English or Hindi). ' +
  'Return ONLY valid JSON with keys: ' +
  'summary (2-3 sentences, English), ' +
  'outcome (one of: interested, not_interested, callback_requested, no_response, wrong_number, other), ' +
  'sentiment (positive | neutral | negative), ' +
  'follow_up_required (boolean), ' +
  'follow_up_when (string, empty if none), ' +
  'key_points (array of short English strings), ' +
  'customer_questions (array of strings).';
const user =
  'Call purpose: ' + ((b.metadata && b.metadata.purpose) || 'n/a') + '\n' +
  'Customer name: ' + (b.name || 'n/a') + '\n\nTranscript:\n' + transcriptText;

return [{
  json: {
    authorized: true,
    has_transcript: hasUserSpeech,
    call_id: b.call_id || '',
    phone: b.phone || '',
    name: b.name || '',
    duration_sec: b.duration_sec || 0,
    end_reason: b.end_reason || '',
    transcript,
    transcript_text: transcriptText,
    groq_key: CONFIG.GROQ_API_KEY,
    groq_body: JSON.stringify({
      model: CONFIG.GROQ_MODEL,
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
    }),
    notify_url: CONFIG.RESULT_WEBHOOK_URL,
    notify_secret: CONFIG.WEBHOOK_SECRET,
  },
}];

const base = $('Prepare Report').first().json;
const g = $input.first().json || {};

let analysis = {
  summary: '',
  outcome: base.has_transcript ? 'other' : 'no_response',
  sentiment: 'neutral',
  follow_up_required: false,
  follow_up_when: '',
  key_points: [],
  customer_questions: [],
};
try {
  const content = g.choices && g.choices[0] && g.choices[0].message && g.choices[0].message.content;
  if (content) analysis = Object.assign(analysis, JSON.parse(content));
} catch (e) {
  analysis.summary = 'Analysis failed: ' + e.message;
}

return [{
  json: {
    event: 'call.completed',
    call_id: base.call_id,
    phone: base.phone,
    name: base.name,
    duration_sec: base.duration_sec,
    end_reason: base.end_reason,
    ended_at: new Date().toISOString(),
    analysis,
    transcript: base.transcript,
    transcript_text: base.transcript_text,
    notify_url: base.notify_url,
    notify_secret: base.notify_secret,
  },
}];

// ================= EDIT THIS CONFIG =================
const CONFIG = {
  WEBHOOK_SECRET: 'change-this-secret',
  CARTESIA_API_KEY: 'YOUR_CARTESIA_API_KEY',
  CARTESIA_VERSION: '2026-03-01',   // Cartesia-Version header (if Telugu is rejected, try another listed version)
  DEFAULT_LANGUAGE: 'te',
};
// =====================================================

const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};
const reject = (status, error) => [{ json: { valid: false, http_status: status, error } }];

if ((headers['x-webhook-secret'] || '') !== CONFIG.WEBHOOK_SECRET) return reject(401, 'unauthorized');

const bin = item.binary || {};
const key = bin.clip ? 'clip' : Object.keys(bin)[0];
if (!key) return reject(400, 'attach the audio as multipart field "clip" (mp3/wav/ogg/webm, 10-30s of clean speech)');
if (!body.name) return reject(400, 'name is required');

return [{
  json: {
    valid: true,
    voice_name: String(body.name).slice(0, 80),
    description: body.description || 'Telugu voice',
    language: body.language || CONFIG.DEFAULT_LANGUAGE,
    cartesia_key: CONFIG.CARTESIA_API_KEY,
    cartesia_version: CONFIG.CARTESIA_VERSION,
  },
  binary: { clip: bin[key] },
}];
